from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_core.common import Modal


class ConfirmationModal(Modal):
    def __init__(self, driver):
        super(ConfirmationModal, self).__init__(driver)

    def confirm(self):
        """
        Clicks confirm button in megazone confirmation modal
        """
        self.click_button("confirmation-modal-confirm")

    def cancel(self):
        """
        Clicks cancel button in megazone confirmation modal
        """
        self.click_button("confirmation-modal-cancel")


class RestartModal(ConfirmationModal):
    def __init__(self, driver):
        super(RestartModal, self).__init__(driver)

    def confirm(self):
        """
        Clicks confirm button in megazone confirmation modal

        :return ConnectionLostModal object
        """
        super(RestartModal, self).confirm()
        return ConnectionLostModal(self._driver)


class ConnectionLostModal(Modal):
    def __init__(self, driver):
        super(ConnectionLostModal, self).__init__(driver)

    def wait_until_ends(self, show_timeout=120, disappear_timeout=300):
        """
        Firstly, wait for show_timeout seconds for modal to appear, and then
        disappear_timeout seconds for it's disapperance, which should conclude
        site restart.

        :param show_timeout: appearance timeout
        :param disappear_timeout: disapperance timeout
        """
        modal_class = "connection-lost-modal"
        self.wait_for_visibility((By.CLASS_NAME, modal_class), show_timeout)
        self.wait_for_invisibility((By.CLASS_NAME, modal_class),
                                   timeout=disappear_timeout)


class SessionTimeoutModal(Modal):
    def __init__(self, driver):
        super(SessionTimeoutModal, self).__init__(driver)

    def wait_until_disappear(self, show_timeout=1800, disappear_timeout=360):
        """
        Wait for show_timeout seconds for modal to appear

        :param show_timeout: appearance timeout
        """
        modal_class = "session-timeout-modal"
        self.wait_for_visibility((By.CLASS_NAME, modal_class), show_timeout)
        self.wait_for_invisibility((By.CLASS_NAME, modal_class),
                                   timeout=disappear_timeout)


class ActivateModal(ConfirmationModal):
    def __init__(self, driver):
        super(ActivateModal, self).__init__(driver)

    def confirm(self):
        modal_xpath = "//div[@id='PE_Activate_Dialog']//button[text()='Activate']"
        self.wait_for_visibility((By.XPATH, modal_xpath), 5)
        self._driver.find_element_by_xpath(modal_xpath).click()

    def cancel(self):
        modal_xpath = "//div[@id='PE_Activate_Dialog']//button[text()='Cancel']"
        self.wait_for_visibility((By.XPATH, modal_xpath), 5)
        self._driver.find_element_by_xpath(modal_xpath).click()


