class RndResetModal(ConfirmationModal):
    def __init__(self, driver):
        super(RndResetModal, self).__init__(driver)

    def confirm(self):
        reset_button_xpath = 'confirmation-modal-confirm'
        self.wait_for_visibility((By.ID, reset_button_xpath), 5)
        self.wait_for_enable((By.ID, reset_button_xpath), 5)
        super(RndResetModal, self).confirm()

    def cancel(self):
        cancel_button_xpath = 'confirmation-modal-cancel'
        self.wait_for_visibility((By.ID, cancel_button_xpath), 5)
        self.wait_for_enable((By.ID, cancel_button_xpath), 5)
        super(RndResetModal, self).cancel()


class RndExitModal(RndResetModal):
    def __init__(self, driver):
        super(RndExitModal, self).__init__(driver)


class InitializeCertificatesModal(RndResetModal):
    def __init__(self, driver):
        super(InitializeCertificatesModal, self).__init__(driver)


class CellsLockUnlockModal(ConfirmationModal):
    def __init__(self, driver):
        super(CellsLockUnlockModal, self).__init__(driver)

    def confirm(self, operation):
        confirm_modal_xpath = "//div[@class='modal-dialog']//button[text()='{}']".format(operation)
        self.wait_for_visibility((By.XPATH, confirm_modal_xpath), 5)
        self._driver.find_element_by_xpath(confirm_modal_xpath).click()

    def cancel(self):
        cancel_modal_xpath = "//div[@class='modal-dialog']//button[text()='Cancel']"
        self.wait_for_visibility((By.XPATH, cancel_modal_xpath), 5)
        self._driver.find_element_by_xpath(cancel_modal_xpath).click()
